let settings={...Core.DEFAULTS},context=null,shared=null,selectedMode='free',phase=0,startedAt=0,transcript=[],words=[],review=[],correct=0,retries=0,exerciseAttempts=0,correctionRepeat=false,comparisonRepeat=false,hebrewUses=0,paused=false,muted=false,recognition=null,sessionId=null,attemptCounts={},answerAnalytics={},mistakeEvents=[],adaptiveEvents=[],awaitingFinish=false,sessionFinished=false;
const $=s=>document.querySelector(s),ready=new Promise(r=>window.EAApp?r():window.addEventListener('ea-app-ready',r,{once:true}));
const turnGuard=Natural.createTurnGuard();let voiceQueue=null,visualTeacher=null,answerPlayback=null,answerStream=null,activeProvider=null,providerEvents=[],availableVoices=[],correctStreak=0,lastPraise='',listenTimer=null,recognitionGeneration=0,microphoneWarmupAttempted=false,lessonTimerId=null,lessonRemainingSeconds=600,lessonTimerTickAt=0,companionCelebrationTimer=null,companionCelebratingUntil=0,pendingEarnedXP=0;
