const speechDebugEnabled=()=>settings.developerDebug||new URLSearchParams(location.search).get('speechDebug')==='1';
function speechLog(event,detail=''){const entry={at:new Date().toISOString(),event,detail:String(detail||'')};speechDebug.events.push(entry);speechDebug.events=speechDebug.events.slice(-24);if(speechDebugEnabled())console.debug('[EA Speech]',event,detail);renderSpeechDebug()}
function probableTeacherEcho(heard,prompt,onsetDelayMs=Infinity){
  const answer=Core.normalize(heard),teacher=Core.normalize(prompt);
  if(!answer||!teacher||onsetDelayMs>500)return false;
  if(teacher.includes(answer)||answer.includes(teacher))return true;
  const answerTokens=Core.tokens(answer),teacherTokens=new Set(Core.tokens(teacher));
  if(!answerTokens.length)return false;
  return answerTokens.filter(token=>teacherTokens.has(token)).length/answerTokens.length>=.75;
}
async function prepareMicrophone(){
  // Called from the lesson-start click. It asks only for permission, releases
  // the stream, and lets SpeechRecognition own the actual listening turn.
  if(microphoneWarmupAttempted||!settings.microphoneEnabled||!navigator.mediaDevices?.getUserMedia)return;
  microphoneWarmupAttempted=true;
  try{
    const stream=await navigator.mediaDevices.getUserMedia({audio:true});
    stream.getTracks?.().forEach(track=>track.stop());
    speechLog('microphone ready for automatic listening');
  }catch(error){speechLog('microphone warmup unavailable',error?.name||'unknown')}
}
function renderSpeechDebug(){const box=$('#speechPipelineDebug');if(!box)return;box.hidden=!speechDebugEnabled();box.textContent=`Microphone: ${speechDebug.microphone}\nRecognition: ${speechDebug.recognition}\nLast transcript: ${speechDebug.lastTranscript}\nCurrent lesson state: ${speechDebug.lessonState}\n\n${speechDebug.events.map(x=>`${x.at.slice(11,23)} ${x.event}${x.detail?`: ${x.detail}`:''}`).join('\n')}`}
function renderLessonTimer(){const box=$('#teacherTimer');if(!box)return;const minutes=Math.floor(lessonRemainingSeconds/60),seconds=lessonRemainingSeconds%60;box.textContent=`⏳ ${minutes}:${String(seconds).padStart(2,'0')}`;box.setAttribute('aria-label',`זמן נותר בשיעור: ${minutes} דקות ו-${seconds} שניות`)}
function stopLessonTimer(){clearInterval(lessonTimerId);lessonTimerId=null}
function startLessonTimer(){stopLessonTimer();lessonTimerTickAt=Date.now();renderLessonTimer();lessonTimerId=setInterval(()=>{if(paused)return;const elapsed=Math.floor((Date.now()-lessonTimerTickAt)/1000);if(elapsed<1)return;lessonRemainingSeconds=Math.max(0,lessonRemainingSeconds-elapsed);lessonTimerTickAt+=elapsed*1000;renderLessonTimer()},300)}

