function loadVoices(attempt=0){availableVoices=window.speechSynthesis?.getVoices?.()||[];if(!availableVoices.length&&attempt<5){setTimeout(()=>loadVoices(attempt+1),120*(attempt+1));return}voiceQueue?.setVoices(availableVoices);const gender=selectedTeacher()?.voiceGender||settings.teacherVoiceGender||'female',english=$('#englishVoice'),hebrew=$('#hebrewVoice');for(const [select,lang,current]of[[english,'en-US',settings.englishVoice],[hebrew,'he-IL',settings.hebrewVoice]])if(select){const ranked=Natural.rankVoices(availableVoices,lang,gender);select.replaceChildren(...ranked.map(v=>{const o=document.createElement('option'),detected=Natural.voiceGender(v),label=detected==='female'?'קול נשי':detected==='male'?'קול גברי':'מגדר לא מדווח';o.value=v.voiceURI||v.name;o.textContent=`${v.name} — ${v.lang} — ${label}${Natural.voiceScore(v,lang)<55?' (קול בסיסי)':''}`;o.selected=o.value===current&&detected===gender;return o}));if(!ranked.length){const o=document.createElement('option');o.textContent='אין קול מתאים במכשיר';select.append(o)}const selected=Natural.chooseVoice(availableVoices,lang,current,gender);if((settings.developerDebug||new URLSearchParams(location.search).has('speechDebug'))&&selected.fallbackReason)console.debug('[EA Voice]',{teacher:selectedTeacher()?.id,lang,requestedGender:gender,voice:selected.voice?.name||null,actualGender:selected.actualGender,pitch:Natural.genderPitch(gender,selected.actualGender),fallback:selected.fallbackReason})}}
