function renderPreflight(message=''){const lesson=context.lesson,advanced=Core.advancedAvailable(settings,teacherAIConfig,navigator.onLine),choose=settings.chooseBeforeLesson&&settings.childMaySwitch;$('#teacherPreflightBody').innerHTML=`${message?`<div class="teacher-warning">${message}</div>`:''}<p><strong>ילד/ה:</strong> ${esc(context.child.name)}</p><p><strong>שיעור:</strong> ${esc(lesson.titleHe||lesson.title)}</p><p><strong>מטרת למידה:</strong> ${esc(lesson.descriptionHe||lesson.description)}</p><p><strong>משך משוער:</strong> 8–12 דקות</p><p><strong>מיקרופון:</strong> ${settings.microphoneEnabled?'מורשה בהגדרות':'חסום בהגדרות'} • <strong>חיבור:</strong> ${navigator.onLine?'מחובר':'לא מקוון'}</p><div class="mode-cards">${modeCard('free','מורה חינמי','חינם','ללא תשלום • עובד לפי מערך השיעור • מתאים לתרגול מובנה',!settings.allowedFree)}${modeCard('advanced','מורה AI מתקדם',advanced.ok?'AI מתקדם':'לא הוגדר','שיחה גמישה יותר • הסברים מותאמים • עשוי להיות כרוך בתשלום',!settings.allowedAdvanced||!choose)}</div><p><strong>המצב שנבחר:</strong> ${selectedMode==='advanced'?'מורה AI מתקדם':'מורה חינמי'}</p><button class="primary" id="teacherBegin">התחלת השיעור</button>`;$('#teacherPreflightBody').querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{if(!choose&&b.dataset.mode!==settings.defaultMode)return;if(b.dataset.mode==='advanced'&&!settings.allowedAdvanced)return;selectedMode=b.dataset.mode;renderPreflight()});$('#teacherBegin').onclick=start}
async function start(){if(Core.needsMicrophone(selectedMode)&&!settings.microphoneEnabled)return fallback('microphone-disabled');const used=minutesToday(selectedMode),limit=selectedMode==='advanced'?settings.advancedDailyMinutes:settings.freeDailyMinutes;if(used>=limit)return selectedMode==='advanced'?fallback('usage-limit'):window.EAApp.showToast('מגבלת הדקות היומית של המורה החינמי הושגה');if(selectedMode==='advanced'){const check=Core.advancedAvailable(settings,teacherAIConfig,navigator.onLine);if(!check.ok)return fallback(check.reason)}window.EAApp.closeModal($('#teacherPreflight'));window.EAApp.openModal('#teacherSession');reset();if(selectedMode==='advanced')startAdvanced().catch(e=>fallback(e.message,true));else if(selectedMode==='mock')startMockLesson();else startFree()}
