function handleConversationIntent(heard,i){
  const result=activeProvider?.handleChildInput?.(heard,{phase:PHASES[phase],lessonId:shared.lessonId,expected:i.answer})||Providers.conversationIntent(heard);
  const intent=result.intent;
  if(intent===Providers.CONVERSATION_INTENTS.ANSWER||intent===Providers.CONVERSATION_INTENTS.YES||intent===Providers.CONVERSATION_INTENTS.NO)return false;
  if(intent===Providers.CONVERSATION_INTENTS.GREETING){speak(`Hello ${context.child.name}! I am listening. ${i.en}`,'en-US',()=>listen(i),'greeting');return true}
  if(intent===Providers.CONVERSATION_INTENTS.THANKS){speak(`You are welcome, ${context.child.name}. ${i.en}`,'en-US',()=>listen(i),'encouragement');return true}
  line(context.child.name,heard);
  if(intent===Providers.CONVERSATION_INTENTS.REPEAT){speakCurrent();return true}
  if(intent===Providers.CONVERSATION_INTENTS.SLOWER){conversationState('teacherSpeaking');voiceQueue.repeatSlower().then(()=>{if(!paused)setTimeout(()=>listen(i),350)});return true}
  if(intent===Providers.CONVERSATION_INTENTS.EXPLAIN){const phrase=(shared.lesson.phrases||[]).find(p=>Core.normalize(p.english).includes(Core.normalize(result.subject)))||shared.lesson.phrases?.[0],meaning=phrase?.hebrew||'זו מילה מהשיעור שלנו';speak(`${result.subject||phrase?.english||'The word'}. ${meaning}.`,'en-US',()=>listen(i),'explanation');return true}
  if(intent===Providers.CONVERSATION_INTENTS.HINT||intent===Providers.CONVERSATION_INTENTS.DONT_KNOW){visualTeacher?.setState('pointing');showAnswers(i,i.validation?.hints?.[0]||'הסתכלו על האפשרויות ובחרו צעד קטן.',2);return true}
  if(intent===Providers.CONVERSATION_INTENTS.TRY_AGAIN){speak("Of course — take your time. I'm listening.",'en-US',()=>listen(i),'encouragement');return true}
  if(intent===Providers.CONVERSATION_INTENTS.BREAK){paused=false;toggleTeacherPause();return true}
  if(intent===Providers.CONVERSATION_INTENTS.STOP){const box=$('#teacherAnswers');box.replaceChildren();for(const [label,action] of [['המשך',()=>listen(i)],['סיום השיעור',()=>finish('child-ended')]]){const button=document.createElement('button');button.className=label==='המשך'?'primary':'danger';button.textContent=label;button.onclick=action;box.append(button)}status('idle','רוצה לסיים או להמשיך?');return true}
  // Outside the explicit opening readiness question this is only a candidate
  // answer. It must pass validation before any success praise is spoken.
  if(intent===Providers.CONVERSATION_INTENTS.READY)return false;
  if(intent===Providers.CONVERSATION_INTENTS.ENCOURAGEMENT){speak("I love that you're enjoying this — let's keep going!",'en-US',()=>listen(i),'celebration');return true}
  if(intent===Providers.CONVERSATION_INTENTS.INSTRUCTION){speak(`עכשיו מקשיבים לשאלה ועונים עליה. אפשר לענות באנגלית או בעברית. ${i.he||i.en}`,'he-IL',()=>listen(i),'explanation');return true}
  if(intent===Providers.CONVERSATION_INTENTS.LESSON_TOPIC){speak(`היום אנחנו לומדים ${shared.lesson.titleHe||shared.lesson.title}. מיד נחזור לשאלה.`,'he-IL',()=>listen(i),'explanation');return true}
  if(intent===Providers.CONVERSATION_INTENTS.LANGUAGE_CHOICE){speak('כן. אפשר לענות באנגלית או בעברית. אם תענו בעברית, אני אעזור גם עם המילה באנגלית.','he-IL',()=>listen(i),'encouragement');return true}
  return false
}
