let lessonCountdownId=null,lessonCountdownRemaining=600,lessonCountdownLast=0,lessonCountdownWasOpen=false;
function installLessonCountdown(){
  const update=()=>{
    const session=$('#teacherSession'),open=!!session?.classList.contains('open');
    if(open&&!lessonCountdownWasOpen){lessonCountdownRemaining=600;lessonCountdownLast=Date.now();lessonCountdownWasOpen=true}
    if(!open){lessonCountdownWasOpen=false;return}
    let box=$('#teacherTimer');
    if(!box){box=document.createElement('output');box.id='teacherTimer';box.className='teacher-timer';box.setAttribute('aria-live','off');$('#teacherStatus')?.after(box)}
    if(!paused){const elapsed=Math.floor((Date.now()-lessonCountdownLast)/1000);if(elapsed>0){lessonCountdownRemaining=Math.max(0,lessonCountdownRemaining-elapsed);lessonCountdownLast+=elapsed*1000}}
    const minutes=Math.floor(lessonCountdownRemaining/60),seconds=lessonCountdownRemaining%60;
    box.textContent=`⏳ ${minutes}:${String(seconds).padStart(2,'0')}`;
    box.setAttribute('aria-label',`זמן נותר בשיעור: ${minutes} דקות ו-${seconds} שניות`);
  };
  document.addEventListener('click',event=>{if(event.target.closest('#teacherPause'))lessonCountdownLast=Date.now()});
  lessonCountdownId=setInterval(update,300);
}
installLessonCountdown();
